using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEngine.AddressableAssets;using Assets.Script.DynamicCards;using Cynthia.Card;
public static class MotionWork {public static void Run(){new GameObject("Final motion verification").AddComponent<FinalMotionVerification>();}}
public class FinalMotionVerification:MonoBehaviour {
const string W="C:/UnityProjects/LegacyGwent/work/DynamicCards/MotionRepair-20260910/FinalMain/";List<GameObject> rows=new List<GameObject>();List<string> errors=new List<string>();object F(object o,string n)=>o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(o);
void Awake(){Application.logMessageReceived+=Log;}void OnDestroy(){Application.logMessageReceived-=Log;foreach(var row in rows)if(row!=null)Destroy(row);}void Log(string m,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors.Add(m+"\n"+stack);File.WriteAllLines(W+"errors.txt",errors);}}
Color32[] Capture(DynamicCardView v,string name){var rt=(RenderTexture)F(v,"texture");var old=RenderTexture.active;RenderTexture.active=rt;var t=new Texture2D(rt.width,rt.height,TextureFormat.RGBA32,false);t.ReadPixels(new Rect(0,0,rt.width,rt.height),0,0);t.Apply();RenderTexture.active=old;File.WriteAllBytes(W+name+".png",t.EncodeToPNG());var pixels=t.GetPixels32();Destroy(t);return pixels;}
IEnumerator Start(){Directory.CreateDirectory(W);var ed=Resources.FindObjectsOfTypeAll<EditorInfo>().First(x=>x.gameObject.scene.IsValid());var all=GwentMap.GetCards(isHasAgent:true).ToList();var ids=new[]{"22005","32015","70093","70159","70013","12022","44032"};var cards=all.Where(x=>ids.Contains(x.CardId)).ToList();ed.SetShowCardInfo(cards);ed.SelectSwitchUICard(cards.First(x=>x.CardId=="70013"));var canvas=ed.GetComponentInParent<Canvas>();if(canvas==null)canvas=FindObjectsOfType<Canvas>().First(c=>c.isRootCanvas);var listInfos=new List<ListCardShowInfo>();foreach(var card in cards.Take(4)){var go=Instantiate(ed.EditorListCardPrefab,canvas.transform,false);rows.Add(go);var rt=go.GetComponent<RectTransform>();rt.anchorMin=rt.anchorMax=new Vector2(.5f,.5f);rt.anchoredPosition=new Vector2(-690,200-listInfos.Count*60);var info=go.GetComponent<ListCardShowInfo>();info.SetCardInfo(card.CardId);listInfos.Add(info);}yield return new WaitForSecondsRealtime(2);var old=listInfos[0];DynamicCardView.Bind(old.Miniature,old.CardStatus.CardArtsId,listThumbnail:true);yield return new WaitForSecondsRealtime(2);old.SetCardInfo(old.CardStatus.CardId);yield return null;var listReport=new List<string>();foreach(var info in listInfos){var handle=Addressables.LoadAssetAsync<Sprite>(info.CardStatus.CardArtsId+"_slot");var expected=handle.WaitForCompletion();bool exact=info.Miniature.sprite==expected;listReport.Add(info.CardStatus.CardArtsId+" originalSlot="+exact+" views="+info.Miniature.GetComponents<DynamicCardView>().Length+" surfaces="+info.Miniature.GetComponentsInChildren<RawImage>(true).Length);Addressables.Release(handle);if(!exact||info.Miniature.GetComponents<DynamicCardView>().Length>0||info.Miniature.GetComponentsInChildren<RawImage>(true).Length>0)throw new Exception("Static deck row regression");}File.WriteAllLines(W+"static-rows.txt",listReport);yield return new WaitForSecondsRealtime(8);var views=FindObjectsOfType<DynamicCardView>().Where(v=>F(v,"texture")!=null).ToArray();var nodes=views.Select(v=>((GameObject)F(v,"model")).GetComponentsInChildren<Transform>(true)).ToArray();var pose=nodes.Select(ns=>ns.Select(t=>t.localRotation).ToArray()).ToArray();var before=views.Select((v,i)=>Capture(v,F(v,"artId")+"-"+F(v,"preview")+"-a")).ToArray();ScreenCapture.CaptureScreenshot(W+"screen-a.png");yield return new WaitForSecondsRealtime(6);var result=new List<string>();for(int i=0;i<views.Length;i++){var v=views[i];if(v==null||F(v,"texture")==null)throw new Exception("Card replaced during final sample");var after=Capture(v,F(v,"artId")+"-"+F(v,"preview")+"-b");long delta=0;for(int p=0;p<after.Length;p++)delta+=Math.Abs(after[p].r-before[i][p].r)+Math.Abs(after[p].g-before[i][p].g)+Math.Abs(after[p].b-before[i][p].b);int moving=nodes[i].Where((t,j)=>Quaternion.Angle(t.localRotation,pose[i][j])>.001f).Count();result.Add(F(v,"artId")+" preview="+F(v,"preview")+" age="+F(v,"age")+" pixels="+delta+" moving="+moving);if(delta==0)throw new Exception("Frozen rendered image "+F(v,"artId"));}File.WriteAllLines(W+"motion.txt",result);ScreenCapture.CaptureScreenshot(W+"screen-b.png");yield return new WaitForEndOfFrame();File.WriteAllText(W+"complete.txt","PASS static original slots, stale animation removal, seven small cards and selected preview; errors="+errors.Count);Destroy(gameObject);}}
